const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// Icon helpers
const { FaFemale, FaMale, FaBrain, FaPills, FaPray, FaComments, FaExclamationTriangle, FaChartBar, FaBalanceScale, FaHeartbeat, FaLightbulb, FaShieldAlt, FaGlobe, FaUserMd } = require("react-icons/fa");

function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

async function main() {
  let pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Our World in Data / IHME";
  pres.title = "The Global Burden of Mental Illness: Prevalence, Impact, and the Treatment Gap";
  pres.subject = "Mental Health Policy Brief";

  // Color palette: Sage Calm adapted for mental health
  const COLORS = {
    primary: "2C5F5F",     // Deep teal (dominant)
    secondary: "5B8C8C",   // Muted teal
    accent: "D4A373",      // Warm sand accent
    light: "F5F5F0",       // Warm off-white
    dark: "1A3A3A",        // Very dark teal
    text: "2D3436",        // Near-black text
    textLight: "F5F5F0",   // Light text
    muted: "7F8C8D",       // Muted gray
    chart1: "2C5F5F",
    chart2: "5B8C8C",
    chart3: "D4A373",
    chart4: "8E9AAF",
    chart5: "CBC0D3",
  };

  // Pre-generate icons
  const icons = {};
  const iconDefs = [
    ["brain", FaBrain, COLORS.accent],
    ["female", FaFemale, COLORS.accent],
    ["male", FaMale, COLORS.secondary],
    ["pills", FaPills, COLORS.primary],
    ["pray", FaPray, COLORS.secondary],
    ["comments", FaComments, COLORS.accent],
    ["warning", FaExclamationTriangle, COLORS.accent],
    ["chart", FaChartBar, COLORS.primary],
    ["scale", FaBalanceScale, COLORS.secondary],
    ["heartbeat", FaHeartbeat, COLORS.accent],
    ["lightbulb", FaLightbulb, COLORS.accent],
    ["shield", FaShieldAlt, COLORS.secondary],
    ["globe", FaGlobe, COLORS.primary],
    ["userMd", FaUserMd, COLORS.accent],
  ];

  for (const [name, Component, color] of iconDefs) {
    icons[name] = await iconToBase64Png(Component, color, 256);
  }

  // ========================
  // SLIDE 1: Title Slide
  // ========================
  let slide1 = pres.addSlide();
  slide1.background = { color: COLORS.dark };
  // Subtle accent bar at top
  slide1.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: "100%", h: 0.08,
    fill: { color: COLORS.accent },
  });
  // Title
  slide1.addText("The Global Burden of Mental Illness", {
    x: 0.8, y: 1.8, w: 8.4, h: 1.0,
    fontSize: 40, fontFace: "Calibri", bold: true,
    color: COLORS.textLight, align: "left", valign: "middle",
  });
  // Subtitle
  slide1.addText("Prevalence, Impact, and the Treatment Gap", {
    x: 0.8, y: 2.7, w: 8.4, h: 0.5,
    fontSize: 22, fontFace: "Calibri", bold: false,
    color: COLORS.accent, align: "left", valign: "middle",
  });
  // Scope line
  slide1.addText("Global data overview | 2023", {
    x: 0.8, y: 3.3, w: 8.4, h: 0.4,
    fontSize: 14, fontFace: "Calibri",
    color: COLORS.muted, align: "left", valign: "middle",
  });
  // Source attribution
