    x: 0.8, y: 4.8, w: 8.4, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: COLORS.muted, align: "left", valign: "middle",
  });
  // Globe icon
  slide1.addImage({
    data: icons.globe,
    x: 8.6, y: 1.9, w: 0.7, h: 0.7,
  });

  // ========================
  // SLIDE 2: Mental Health Scale (Prevalence)
  // ========================
  let slide2 = pres.addSlide();
  slide2.background = { color: COLORS.light };
  // Title
  slide2.addText("Hundreds of Millions Affected: 1 in 3 Women and 1 in 5 Men Face Major Depression", {
    x: 0.5, y: 0.35, w: 9.0, h: 0.7,
    fontSize: 26, fontFace: "Calibri", bold: true,
    color: COLORS.text, align: "left", valign: "middle",
  });
  // Two large callout cards
  // Women card
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.3, w: 4.0, h: 2.4,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.1 },
  });
  slide2.addImage({
    data: icons.female,
    x: 1.0, y: 1.55, w: 0.6, h: 0.6,
  });
  slide2.addText("1 in 3", {
    x: 1.8, y: 1.5, w: 2.5, h: 0.7,
    fontSize: 56, fontFace: "Calibri", bold: true,
    color: COLORS.primary, align: "left", valign: "middle",
  });
  slide2.addText("women will experience\nmajor depression in their lifetime", {
    x: 1.0, y: 2.3, w: 3.4, h: 0.9,
    fontSize: 16, fontFace: "Calibri",
    color: COLORS.text, align: "left", valign: "top",
  });

  // Men card
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.3, w: 4.0, h: 2.4,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.1 },
  });
  slide2.addImage({
    data: icons.male,
    x: 5.7, y: 1.55, w: 0.6, h: 0.6,
  });
  slide2.addText("1 in 5", {
    x: 6.5, y: 1.5, w: 2.5, h: 0.7,
    fontSize: 56, fontFace: "Calibri", bold: true,
    color: COLORS.secondary, align: "left", valign: "middle",
  });
  slide2.addText("men will experience\nmajor depression in their lifetime", {
    x: 5.7, y: 2.3, w: 3.4, h: 0.9,
    fontSize: 16, fontFace: "Calibri",
    color: COLORS.text, align: "left", valign: "top",
  });

  // Bottom text block
  slide2.addText("Mental health conditions span from common disorders (depression, anxiety) to less common but severe conditions (schizophrenia, bipolar disorder). Poor mental health affects well-being, work capacity, and relationships with friends, family, and community.", {
    x: 0.6, y: 4.0, w: 8.7, h: 1.0,
    fontSize: 14, fontFace: "Calibri",
    color: COLORS.text, align: "left", valign: "top",
  });

  // ========================
  // SLIDE 3: Burden by Category (Horizontal Bar Chart)
  // ========================
  let slide3 = pres.addSlide();
  slide3.background = { color: COLORS.light };
  slide3.addText("Depression and Anxiety Dominate: ~695 and ~687 DALYs per 100K Respectively", {
    x: 0.5, y: 0.35, w: 9.0, h: 0.7,
    fontSize: 26, fontFace: "Calibri", bold: true,
    color: COLORS.text, align: "left", valign: "middle",
  });

  // Horizontal bar chart
  slide3.addChart(pres.charts.BAR, [{
    name: "DALYs per 100,000",
    labels: ["Depressive disorders", "Anxiety disorders", "Schizophrenia", "Bipolar disorder", "Eating disorders"],
    values: [694.6, 686.5, 210.2, 94.6, 47.5],
  }], {
    x: 0.5, y: 1.2, w: 9.0, h: 3.6,
    barDir: "bar",
    barGrouping: "clustered",
    chartColors: [COLORS.primary],
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
    catAxisLabelColor: COLORS.text,
    valAxisLabelColor: COLORS.muted,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.text,
    dataLabelFontSize: 11,
    showLegend: false,
    title: "Disease Burden by Category of Mental Illness (World, 2023)",
    titleFontSize: 14,
    titleColor: COLORS.muted,
    titleBold: false,
    valAxisTitle: "DALYs per 100,000 people",
    valAxisTitleFontSize: 11,
    valAxisTitleColor: COLORS.muted,
    catAxisLabelFontSize: 12,
    valAxisLabelFontSize: 11,
  });

  slide3.addText("Source: IHME, Global Burden of Disease (2025) via Our World in Data", {
    x: 0.5, y: 5.0, w: 9.0, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: COLORS.muted, align: "left", valign: "middle",
  });

  // ========================
  // SLIDE 4: Depression vs Anxiety Parity
  // ========================
  let slide4 = pres.addSlide();
  slide4.background = { color: COLORS.light };
  slide4.addText("Depression and Anxiety Carry Nearly Equal Disease Burden Worldwide", {
    x: 0.5, y: 0.35, w: 9.0, h: 0.7,
    fontSize: 26, fontFace: "Calibri", bold: true,
    color: COLORS.text, align: "left", valign: "middle",
  });

  // Side-by-side paired bar chart
  slide4.addChart(pres.charts.BAR, [
    {
      name: "Depressive disorders",
      labels: ["DALYs per 100K"],
      values: [694.6],
    },
    {
      name: "Anxiety disorders",
      labels: ["DALYs per 100K"],
      values: [686.5],
    },
  ], {
    x: 0.5, y: 1.2, w: 9.0, h: 3.2,
    barDir: "col",
    barGrouping: "clustered",
    chartColors: [COLORS.primary, COLORS.secondary],
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
    catAxisLabelColor: COLORS.text,
    valAxisLabelColor: COLORS.muted,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.text,
    dataLabelFontSize: 14,
    showLegend: true,
    legendPos: "b",
    legendFontSize: 12,
    legendColor: COLORS.text,
    valAxisMaxVal: 800,
    valAxisLabelFontSize: 11,
    catAxisLabelFontSize: 12,
  });

  // Key insight text
  slide4.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.6, w: 9.0, h: 0.7,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide4.addText("Together, depressive and anxiety disorders account for roughly 80% of the total mental health disease burden across these five categories.", {
    x: 0.7, y: 4.6, w: 8.6, h: 0.7,
    fontSize: 14, fontFace: "Calibri", bold: false,
    color: COLORS.text, align: "left", valign: "middle",
  });

  // ========================
