    labels: ["Depressive", "Anxiety", "Schizophrenia", "Bipolar", "Eating disorders"],
    values: [694.6, 686.5, 210.2, 94.6, 47.5],
  }], {
    x: 0.5, y: 1.2, w: 9.0, h: 3.0,
    barDir: "col",
    barGrouping: "clustered",
    chartColors: [COLORS.chart3],
