    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.text,
    dataLabelFontSize: 11,
    showLegend: false,
    valAxisLabelFontSize: 11,
    catAxisLabelFontSize: 12,
  });

  // Two insight cards
  slide5.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.4, w: 4.3, h: 0.9,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide5.addText("Schizophrenia: 210.2 DALYs per 100K", {
    x: 0.7, y: 4.4, w: 3.9, h: 0.45,
    fontSize: 14, fontFace: "Calibri", bold: true,
    color: COLORS.primary, align: "left", valign: "middle",
  });
  slide5.addText("Severe disability despite lower prevalence", {
    x: 0.7, y: 4.75, w: 3.9, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: COLORS.muted, align: "left", valign: "middle",
  });

  slide5.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 4.4, w: 4.3, h: 0.9,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide5.addText("Bipolar disorder: 94.6 DALYs per 100K", {
    x: 5.4, y: 4.4, w: 3.9, h: 0.45,
    fontSize: 14, fontFace: "Calibri", bold: true,
    color: COLORS.secondary, align: "left", valign: "middle",
  });
  slide5.addText("Smaller but meaningful individual burden", {
    x: 5.4, y: 4.75, w: 3.9, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: COLORS.muted, align: "left", valign: "middle",
  });

  // ========================
  // SLIDE 6: Treatment Gap
  // ========================
  let slide6 = pres.addSlide();
  slide6.background = { color: COLORS.light };
  slide6.addText("Treatment Is Available but Often Lacking or Poor Quality", {
    x: 0.5, y: 0.35, w: 9.0, h: 0.7,
    fontSize: 26, fontFace: "Calibri", bold: true,
    color: COLORS.text, align: "left", valign: "middle",
  });

  // Four icon cards in a row
  const gapItems = [
    { icon: "warning", title: "Stigma", desc: "Many people are uncomfortable disclosing symptoms to healthcare professionals or even to people they know." },
    { icon: "globe", title: "Access", desc: "Treatment is often lacking, especially in low- and middle-income countries." },
    { icon: "userMd", title: "Quality", desc: "Even where treatment exists, it may be of poor quality." },
    { icon: "chart", title: "Underreporting", desc: "Discomfort with disclosure makes it difficult to estimate true prevalence." },
  ];

  gapItems.forEach((item, i) => {
    const x = 0.5 + i * 2.35;
    slide6.addShape(pres.shapes.RECTANGLE, {
      x: x, y: 1.3, w: 2.15, h: 2.8,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.1 },
    });
