    slide6.addShape(pres.shapes.OVAL, {
      x: x + 0.7, y: 1.55, w: 0.75, h: 0.75,
      fill: { color: COLORS.light },
    });
    slide6.addImage({
      data: icons[item.icon],
      x: x + 0.85, y: 1.7, w: 0.45, h: 0.45,
    });
    slide6.addText(item.title, {
      x: x + 0.1, y: 2.45, w: 1.95, h: 0.4,
      fontSize: 16, fontFace: "Calibri", bold: true,
      color: COLORS.primary, align: "center", valign: "middle",
    });
    slide6.addText(item.desc, {
      x: x + 0.1, y: 2.9, w: 1.95, h: 1.0,
      fontSize: 12, fontFace: "Calibri",
      color: COLORS.text, align: "center", valign: "top",
    });
  });

  // Bottom insight
  slide6.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.35, w: 9.0, h: 0.7,
    fill: { color: COLORS.dark },
  });
  slide6.addText("Mental illnesses are treatable and their impact can be reduced. The actual burden may be higher than reported figures suggest.", {
    x: 0.7, y: 4.35, w: 8.6, h: 0.7,
    fontSize: 14, fontFace: "Calibri",
    color: COLORS.textLight, align: "left", valign: "middle",
  });

  // ========================
  // SLIDE 7: Coping and Response
  // ========================
  let slide7 = pres.addSlide();
  slide7.background = { color: COLORS.light };
  slide7.addText("How People Cope: From Medication to Faith to Family Conversations", {
    x: 0.5, y: 0.35, w: 9.0, h: 0.7,
    fontSize: 26, fontFace: "Calibri", bold: true,
    color: COLORS.text, align: "left", valign: "middle",
  });

  // Three coping strategy cards
  const copingItems = [
    { icon: "pills", title: "Prescribed Medication", desc: "Common in higher-income settings as a primary treatment approach." },
    { icon: "pray", title: "Religious or Spiritual Activities", desc: "Prevalent in many regions worldwide as a coping mechanism." },
    { icon: "comments", title: "Talking to Friends or Family", desc: "A widely reported social support strategy across cultures." },
  ];

  copingItems.forEach((item, i) => {
    const x = 0.5 + i * 3.15;
    slide7.addShape(pres.shapes.RECTANGLE, {
      x: x, y: 1.3, w: 2.9, h: 2.6,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.1 },
    });
    slide7.addShape(pres.shapes.OVAL, {
      x: x + 1.075, y: 1.55, w: 0.75, h: 0.75,
      fill: { color: COLORS.light },
    });
    slide7.addImage({
      data: icons[item.icon],
      x: x + 1.225, y: 1.7, w: 0.45, h: 0.45,
    });
    slide7.addText(item.title, {
      x: x + 0.15, y: 2.45, w: 2.6, h: 0.4,
      fontSize: 16, fontFace: "Calibri", bold: true,
      color: COLORS.primary, align: "center", valign: "middle",
    });
    slide7.addText(item.desc, {
      x: x + 0.15, y: 2.9, w: 2.6, h: 0.8,
      fontSize: 13, fontFace: "Calibri",
      color: COLORS.text, align: "center", valign: "top",
    });
  });

  // Bottom insight
  slide7.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.2, w: 9.0, h: 0.8,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide7.addText("The diversity of coping strategies underscores that mental health responses are shaped by cultural, economic, and healthcare system factors. Policy interventions must account for these differences rather than applying a one-size-fits-all approach.", {
    x: 0.7, y: 4.2, w: 8.6, h: 0.8,
    fontSize: 13, fontFace: "Calibri",
    color: COLORS.text, align: "left", valign: "middle",
  });

  // ========================
  // SLIDE 8: Takeaways and Implications
  // ========================
  let slide8 = pres.addSlide();
  slide8.background = { color: COLORS.dark };
  // Accent bar
  slide8.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: "100%", h: 0.08,
    fill: { color: COLORS.accent },
  });
  slide8.addText("Key Takeaways: Prioritizing Depression, Anxiety, and Closing the Treatment Gap", {
    x: 0.5, y: 0.4, w: 9.0, h: 0.7,
    fontSize: 26, fontFace: "Calibri", bold: true,
    color: COLORS.textLight, align: "left", valign: "middle",
  });

  const takeaways = [
    "Depression and anxiety together represent the overwhelming majority of mental health DALYs.",
    "Schizophrenia and bipolar carry disproportionate individual burden relative to their prevalence.",
    "Treatment exists but access and quality remain inadequate across much of the world.",
    "Stigma suppresses both help-seeking and accurate data, masking the true scale of need.",
    "Policy should prioritize scaling evidence-based interventions for common mental disorders while maintaining specialized care for severe conditions.",
  ];

  takeaways.forEach((text, i) => {
    const y = 1.3 + i * 0.75;
    // Number circle
    slide8.addShape(pres.shapes.OVAL, {
      x: 0.6, y: y + 0.05, w: 0.45, h: 0.45,
      fill: { color: COLORS.accent },
    });
    slide8.addText(String(i + 1), {
      x: 0.6, y: y + 0.05, w: 0.45, h: 0.45,
      fontSize: 16, fontFace: "Calibri", bold: true,
      color: COLORS.dark, align: "center", valign: "middle",
    });
    slide8.addText(text, {
      x: 1.2, y: y, w: 8.0, h: 0.55,
      fontSize: 15, fontFace: "Calibri",
      color: COLORS.textLight, align: "left", valign: "middle",
    });
  });

  // Source
  slide8.addText("Source: IHME, Global Burden of Disease (2025) | Our World in Data (2023)", {
    x: 0.5, y: 5.1, w: 9.0, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: COLORS.muted, align: "left", valign: "middle",
  });

  // Write file
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Presentation saved to /app/output/final_deck.pptx");
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

