// Icon helpers
const { FaFemale, FaMale, FaBrain, FaPills, FaPray, FaComments, FaExclamationTriangle, FaChartBar, FaBalanceScale, FaHeartbeat, FaLightbulb, FaShieldAlt, FaGlobe, FaUserMd } = require("react-icons/fa");

