async function main() {
  let pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Our World in Data / IHME";
  pres.title = "The Global Burden of Mental Illness: Prevalence, Impact, and the Treatment Gap";
  pres.subject = "Mental Health Policy Brief";

  // Color palette: Deep teal + warm sand for mental health
  const COLORS = {
    primary: "2C5F5F",     // Deep teal (dominant)
    secondary: "5B8C8C",   // Muted teal
    accent: "D4A373",      // Warm sand accent
    light: "F5F5F0",       // Warm off-white
    dark: "1A3A3A",        // Very dark teal
    text: "2D3436",        // Near-black text
    textLight: "F5F5F0",   // Light text
    muted: "7F8C8D",       // Muted gray
    chart1: "2C5F5F",
    chart2: "5B8C8C",
    chart3: "D4A373",
    chart4: "8E9AAF",
    chart5: "CBC0D3",
  };

  // Pre-generate icons
  const icons = {};
